"""GitHub API 客户端：自动带 Token、区分错误类型、限流退避一次。"""

import os
import time

import httpx

GITHUB_API = "https://api.github.com"


class GitHubClient:
    """封装 GitHub REST API 调用，错误以结构化 dict 返回，不静默吞掉。"""

    def __init__(self, token: str | None = None, base_url: str = GITHUB_API):
        self.token = token or os.getenv("GITHUB_TOKEN", "")
        self.base_url = base_url
        self.headers = {
            "Accept": "application/vnd.github+json",
            "User-Agent": "github-project-agent",
        }
        if self.token:
            self.headers["Authorization"] = f"Bearer {self.token}"
        self.client = httpx.Client(base_url=self.base_url, headers=self.headers, timeout=20)
        self.last_rate = {}

    def _record_rate(self, resp: httpx.Response) -> None:
        self.last_rate = {
            "limit": resp.headers.get("X-RateLimit-Limit"),
            "remaining": resp.headers.get("X-RateLimit-Remaining"),
            "reset": resp.headers.get("X-RateLimit-Reset"),
        }

    def get(self, path: str, params: dict | None = None, _retried: bool = False) -> dict:
        if not self.token:
            return {
                "ok": False,
                "status": 401,
                "error_type": "missing_token",
                "message": "未配置 GITHUB_TOKEN，请在 .env 中设置后重试。",
            }

        resp = self.client.get(path, params=params)
        self._record_rate(resp)

        if resp.status_code == 401:
            return {
                "ok": False,
                "status": 401,
                "error_type": "auth",
                "message": "Token 无效或已过期，请重新生成。",
            }

        if resp.status_code == 404:
            return {
                "ok": False,
                "status": 404,
                "error_type": "not_found",
                "message": "资源不存在或当前 Token 无权访问。",
            }

        if resp.status_code == 403 or resp.status_code == 429:
            retry_after = resp.headers.get("Retry-After")
            remaining = resp.headers.get("X-RateLimit-Remaining")
            is_rate_limited = resp.status_code == 429 or remaining == "0" or retry_after is not None
            if is_rate_limited and not _retried:
                wait = int(retry_after) if retry_after and retry_after.isdigit() else 60
                time.sleep(wait)
                return self.get(path, params=params, _retried=True)
            return {
                "ok": False,
                "status": resp.status_code,
                "error_type": "rate_limit" if is_rate_limited else "forbidden",
                "message": "触发 GitHub 限流，已退避重试一次仍失败。" if is_rate_limited else "当前 Token 权限不足。",
                "retry_after": retry_after,
            }

        if resp.status_code >= 400:
            return {
                "ok": False,
                "status": resp.status_code,
                "error_type": "http_error",
                "message": f"GitHub 返回错误：{resp.status_code}",
            }

        return {
            "ok": True,
            "status": resp.status_code,
            "data": resp.json(),
            "rate": self.last_rate,
        }

"""GitHub 工具层单测：用假客户端返回构造好的响应，不真调 API。"""

import base64
import unittest

import tools


class FakeClient:
    def __init__(self, payloads):
        self.payloads = payloads
        self.calls = []

    def get(self, path, params=None):
        self.calls.append((path, params))
        return self.payloads[path]


def use_fake(payloads):
    fake = FakeClient(payloads)
    tools._client = fake
    return fake


class RepoInfoTest(unittest.TestCase):
    def test_extracts_fields(self):
        use_fake({
            "/repos/o/r": {
                "ok": True,
                "status": 200,
                "data": {
                    "full_name": "o/r", "description": "demo", "default_branch": "main",
                    "language": "Python", "stargazers_count": 3, "forks_count": 1,
                    "open_issues_count": 0, "updated_at": "2026-11-07T10:00:00Z",
                    "html_url": "https://github.com/o/r",
                },
            }
        })
        info = tools.get_repo_info("o", "r")
        self.assertTrue(info["ok"])
        self.assertEqual(info["default_branch"], "main")
        self.assertEqual(info["stars"], 3)


class FileTreeTest(unittest.TestCase):
    def test_keeps_only_blobs_and_truncates(self):
        tree = [{"path": f"f{i}.py", "type": "blob"} for i in range(tools.MAX_TREE_ENTRIES + 5)]
        tree.append({"path": "src", "type": "tree"})
        use_fake({
            "/repos/o/r/git/trees/main": {"ok": True, "status": 200, "data": {"tree": tree}}
        })
        result = tools.get_file_tree("o", "r")
        self.assertEqual(result["count"], tools.MAX_TREE_ENTRIES + 5)
        self.assertTrue(result["truncated"])
        self.assertEqual(len(result["files"]), tools.MAX_TREE_ENTRIES)
        self.assertNotIn("src", result["files"])


class FileContentTest(unittest.TestCase):
    def test_decodes_small_file(self):
        raw = "print('hi')\n"
        use_fake({
            "/repos/o/r/contents/a.py": {
                "ok": True,
                "status": 200,
                "data": {
                    "path": "a.py",
                    "size": len(raw),
                    "encoding": "base64",
                    "content": base64.b64encode(raw.encode()).decode(),
                },
            }
        })
        result = tools.get_file_content("o", "r", "a.py")
        self.assertFalse(result["truncated"])
        self.assertEqual(result["content"], raw)

    def test_oversize_returns_metadata_only(self):
        use_fake({
            "/repos/o/r/contents/big.py": {
                "ok": True,
                "status": 200,
                "data": {"path": "big.py", "size": 500_000, "encoding": "none", "content": ""},
            }
        })
        result = tools.get_file_content("o", "r", "big.py")
        self.assertTrue(result["truncated"])
        self.assertNotIn("content", result)

    def test_propagates_error(self):
        use_fake({
            "/repos/o/r/contents/missing.py": {
                "ok": False, "status": 404, "error_type": "not_found", "message": "资源不存在",
            }
        })
        result = tools.get_file_content("o", "r", "missing.py")
        self.assertFalse(result["ok"])
        self.assertEqual(result["error_type"], "not_found")


if __name__ == "__main__":
    unittest.main()

